import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
async function fixture(t,options={}) {
  const server=await testServer(options);t.after(()=>server.close());
  const clients={},users={};
  for(const role of ['owner','admin','member','guest','outsider']){
    clients[role]=server.agent();users[role]=(await clients[role]('POST','/auth/signup',{name:'Administration '+role,email:role+'@admin.test',password:'correct-horse-battery'})).data.user;
  }
  const owner=clients.owner,org=(await owner('POST','/orgs',{name:'Administration scope'})).data.organization;
  for(const role of ['admin','member','guest'])assert.equal((await owner('POST','/orgs/'+org.id+'/members',{userId:users[role].id,role})).status,201);
  const project=(await owner('POST','/orgs/'+org.id+'/projects',{key:'FIRST',name:'First project'})).data.project;
  const otherOrg=(await clients.outsider('POST','/orgs',{name:'Other organization'})).data.organization;
  const otherProject=(await clients.outsider('POST','/orgs/'+otherOrg.id+'/projects',{key:'OTHER',name:'Secret other project'})).data.project;
  const path='/orgs/'+org.id+'/members/'+users.guest.id;
  async function token(scopes){return (await owner('POST','/tokens',{name:'Scoped proof',scopes})).data.token;}
  async function scoped(credential,route,method='GET',body){return owner(method,route,body,{authorization:'Bearer '+credential});}
  return {...server,clients,users,owner,org,project,otherOrg,otherProject,path,token,scoped};
}
test('member access projection allows owner/admin and denies member/guest/other organization',async t=>{
  const f=await fixture(t);
  for(const suffix of ['/access','/projects']){
    for(const role of ['owner','admin']){const r=await f.clients[role]('GET',f.path+suffix);assert.equal(r.status,200);}
    for(const role of ['member','guest','outsider'])assert.equal((await f.clients[role]('GET',f.path+suffix)).status,403);
    assert.equal((await f.agent()('GET',f.path+suffix)).status,401);
  }
  assert.equal((await f.owner('GET','/orgs/'+f.org.id+'/members/'+f.users.outsider.id+'/access')).status,404);
});
test('member access projection requires both canonical administration scopes',async t=>{
  const f=await fixture(t);
  for(const scopes of [['members:manage'],['project:manage'],['org:read'],['audit:read']]){
    const credential=await f.token(scopes);
    for(const suffix of ['/access','/projects'])assert.equal((await f.scoped(credential,f.path+suffix)).status,403);
  }
  const credential=await f.token(['members:manage','project:manage']);
  assert.equal((await f.scoped(credential,f.path+'/access')).data.membership.userId,f.users.guest.id);
  assert.equal((await f.scoped(credential,f.path+'/projects')).data.items[0].id,f.project.id);
});
test('project choices traverse over 200 projects with query-bound cursors and selected resolution',async t=>{
  const f=await fixture(t),db=f.ctx.db;
  const insert=db.prepare('INSERT INTO projects (id,org_id,key,name,description,archived,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)');
  for(let n=0;n<220;n++)insert.run('large-'+n,f.org.id,'P'+String(n).padStart(3,'0'),'Project '+n,'',n===219?1:0,f.ctx.now(),f.ctx.now());
  const ids=[];let cursor;
  do{const r=await f.owner('GET',f.path+'/projects?limit=37'+(cursor?'&cursor='+encodeURIComponent(cursor):''));assert.equal(r.status,200);assert.equal(r.data.total,221);assert.ok(r.data.items.length<=37);ids.push(...r.data.items.map(row=>row.id));cursor=r.data.nextCursor;}while(cursor);
  assert.equal(new Set(ids).size,221);assert.ok(!ids.includes(f.otherProject.id));
  const found=await f.owner('GET',f.path+'/projects?q=P219');assert.equal(found.data.items[0].archived,true);
  const selected=await f.owner('GET',f.path+'/projects?id=large-219&q=absent');assert.equal(selected.data.items[0].name,'Project 219');
  const first=await f.owner('GET',f.path+'/projects?limit=1');
  assert.equal((await f.owner('GET',f.path+'/projects?q=changed&cursor='+encodeURIComponent(first.data.nextCursor))).status,422);
  assert.deepEqual((await f.owner('GET',f.path+'/projects?id='+f.otherProject.id)).data.items,[]);
});
test('direct grants become dormant and effective again while canonical HTTP project access follows roles',async t=>{
  const f=await fixture(t),guest=f.clients.guest;
  assert.equal((await guest('GET','/projects/'+f.project.id)).status,403);
  assert.equal((await f.owner('POST','/projects/'+f.project.id+'/guests',{userId:f.users.guest.id})).status,201);
  assert.equal((await guest('GET','/projects/'+f.project.id)).status,200);
  let access=(await f.owner('GET',f.path+'/access')).data;assert.equal(access.counts.direct,1);assert.equal(access.roles.find(row=>row.role==='guest').effectiveProjects,1);
  assert.equal((await f.owner('PATCH',f.path,{role:'member',expectedRevision:access.membership.revision})).status,200);
  const dormant=(await f.owner('GET',f.path+'/projects?mode=direct')).data.items[0];assert.equal(dormant.dormant,true);assert.equal(dormant.effective,true);
  assert.equal((await f.owner('POST','/projects/'+f.project.id+'/guests',{userId:f.users.guest.id})).status,422);
  access=(await f.owner('GET',f.path+'/access')).data;
  assert.equal((await f.owner('PATCH',f.path,{role:'guest',expectedRevision:access.membership.revision})).status,200);
  assert.equal((await guest('GET','/projects/'+f.project.id)).status,200);
  assert.equal((await f.owner('DELETE','/projects/'+f.project.id+'/guests/'+f.users.guest.id)).status,200);
  assert.equal((await guest('GET','/projects/'+f.project.id)).status,403);
});
test('grant mutations deny wrong organization and scoped/role callers with positive admin controls',async t=>{
  const f=await fixture(t),route='/projects/'+f.project.id+'/guests',body={userId:f.users.guest.id};
  for(const role of ['member','guest','outsider'])assert.equal((await f.clients[role]('POST',route,body)).status,403);
  assert.equal((await f.clients.admin('POST','/projects/'+f.otherProject.id+'/guests',body)).status,403);
  assert.equal((await f.clients.admin('POST',route,body)).status,201);
  const credential=await f.token(['members:manage']);assert.equal((await f.scoped(credential,route+'/'+body.userId,'DELETE')).status,403);
  assert.equal((await f.clients.admin('DELETE',route+'/'+body.userId)).status,200);
});
test('role preview preserves last-owner and owner-only constraints and stale target produces no event',async t=>{
  const f=await fixture(t),ownerPath='/orgs/'+f.org.id+'/members/'+f.users.owner.id;
  const owner=(await f.owner('GET',ownerPath+'/access')).data;
  assert.equal(owner.lastOwner,true);assert.equal(owner.roles.find(row=>row.role==='guest').selectable,false);
  const admin=(await f.clients.admin('GET',ownerPath+'/access')).data;assert.equal(admin.canChangeRole,false);
  assert.equal((await f.clients.admin('PATCH',ownerPath,{role:'member'})).status,403);
  assert.equal((await f.owner('PATCH',ownerPath,{role:'guest'})).status,409);
  const before=(await f.owner('GET',f.path+'/access')).data.membership;
  await f.owner('PATCH',f.path,{role:'member'});
  let events=0;const unsubscribe=f.ctx.bus.subscribe(()=>events++);
  const stale=await f.owner('PATCH',f.path,{role:'admin',expectedRevision:before.revision});unsubscribe();
  assert.equal(stale.status,409);assert.equal(stale.data.error.details.current.role,'member');assert.equal(events,0);
});
test('organization revisions reject same-timestamp peer overwrites and require authorization before snapshots',async t=>{
  const f=await fixture(t),route='/orgs/'+f.org.id;
  f.ctx.db.exec('CREATE TEMP TRIGGER preserve_org_time AFTER UPDATE ON organizations BEGIN UPDATE organizations SET updated_at=old.updated_at WHERE id=new.id; END;');
  const before=(await f.owner('GET',route)).data.organization;
  const peer=await f.owner('PATCH',route,{name:'Peer organization',expectedRevision:before.revision});assert.equal(peer.status,200);assert.equal(peer.data.organization.updatedAt,before.updatedAt);assert.notEqual(peer.data.organization.revision,before.revision);
  let events=0;const unsubscribe=f.ctx.bus.subscribe(()=>events++);
  const stale=await f.owner('PATCH',route,{name:'Lost draft',expectedRevision:before.revision});unsubscribe();
  assert.equal(stale.status,409);assert.equal(stale.data.error.details.current.name,'Peer organization');assert.equal(events,0);
  const denied=await f.clients.member('PATCH',route,{name:'Denied',expectedRevision:before.revision});assert.equal(denied.status,403);assert.equal(denied.data.error.details?.current,undefined);
  assert.equal((await f.owner('PATCH',route,{name:'Chosen draft',expectedRevision:peer.data.organization.revision})).status,200);
  const later=await f.owner('PATCH',route,{name:'Later peer'});assert.equal(later.status,200);
  assert.equal((await f.owner('PATCH',route,{name:'Stale after decision',expectedRevision:peer.data.organization.revision})).status,409);
});
test('team revisions protect independent peer changes at same timestamp and do not leak denied current snapshots',async t=>{
  const f=await fixture(t);
  f.ctx.db.exec('CREATE TEMP TRIGGER preserve_team_time AFTER UPDATE ON teams BEGIN UPDATE teams SET updated_at=old.updated_at WHERE id=new.id; END;');
  const team=(await f.owner('POST','/orgs/'+f.org.id+'/teams',{name:'Original team',description:'Before'})).data.team,route='/teams/'+team.id;
  const peer=(await f.owner('PATCH',route,{name:'Peer team',description:'Independent description',expectedRevision:team.revision})).data.team;assert.equal(peer.updatedAt,team.updatedAt);assert.notEqual(peer.revision,team.revision);
  let events=0;const unsubscribe=f.ctx.bus.subscribe(()=>events++);const stale=await f.owner('PATCH',route,{name:'Mine',description:'Before',expectedRevision:team.revision});unsubscribe();
  assert.equal(stale.status,409);assert.equal(stale.data.error.details.current.description,'Independent description');assert.equal(events,0);
  const denied=await f.clients.outsider('PATCH',route,{name:'Mine',description:'Before',expectedRevision:team.revision});assert.equal(denied.status,403);assert.equal(denied.data.error.details?.current,undefined);
  assert.equal((await f.owner('PATCH',route,{name:'Mine',description:peer.description,expectedRevision:peer.revision})).status,200);
});
test('audit choice projection and project filtering support audit-only tokens without unrelated scope grants',async t=>{
  const f=await fixture(t);await f.owner('POST','/projects/'+f.project.id+'/guests',{userId:f.users.guest.id});
  const credential=await f.token(['audit:read']);
  for(const type of ['actors','targets','projects','actions']){const r=await f.scoped(credential,'/orgs/'+f.org.id+'/audit-options?type='+type);assert.equal(r.status,200);assert.ok(r.data.items.length>0);assert.ok(!JSON.stringify(r.data).includes(f.otherProject.id));}
  const audit=await f.scoped(credential,'/orgs/'+f.org.id+'/audit?projectId='+f.project.id);assert.equal(audit.status,200);assert.ok(audit.data.items.every(row=>row.projectId===f.project.id));
  assert.equal((await f.scoped(credential,'/projects/'+f.project.id)).status,403);
  assert.equal((await f.scoped(credential,'/orgs/'+f.org.id+'/members')).status,403);
  assert.equal((await f.scoped(credential,'/orgs/'+f.org.id+'/audit?projectId='+f.otherProject.id)).status,422);
});
test('audit choices deny member guest outsider and wrong token with session-only self boundaries',async t=>{
  const f=await fixture(t),route='/orgs/'+f.org.id+'/audit-options?type=actors';
  for(const role of ['member','guest','outsider'])assert.equal((await f.clients[role]('GET',route)).status,403);
  assert.equal((await f.clients.admin('GET',route)).status,200);
  assert.equal((await f.agent()('GET',route)).status,401);
  assert.equal((await f.scoped(await f.token(['org:read']),route)).status,403);
  const own=await f.owner('GET','/me/audit-options?type=actors');assert.equal(own.status,200);assert.ok(own.data.items.every(item=>item.id===f.users.owner.id));
});
test('audit options search selected labels and safe payloads come only from sanitized visible events',async t=>{
  const f=await fixture(t);
  f.ctx.bus.emit({actorId:f.users.owner.id,orgId:f.org.id,entityType:'team',entityId:'historical-target',action:'updated',before:{name:'Before safe',password:'not-visible'},after:{name:'After safe',token:'not-visible',link:'not-visible'},time:f.ctx.now()});
  const query='/orgs/'+f.org.id+'/audit-options?type=targets&entityType=team';
  const found=await f.owner('GET',query+'&q=After');assert.equal(found.data.items[0].label,'After safe');assert.ok(!JSON.stringify(found.data).includes('not-visible'));
  assert.equal((await f.owner('GET',query+'&q=missing&id=historical-target')).data.items[0].label,'After safe');
  assert.deepEqual((await f.owner('GET',query+'&id='+f.otherProject.id)).data.items,[]);
  const events=(await f.owner('GET','/orgs/'+f.org.id+'/audit?entityId=historical-target')).data.items;assert.deepEqual(events[0].after,{name:'After safe'});
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {createServer} from 'node:http';
import {once} from 'node:events';
import {build} from 'esbuild';
import {testServer} from '../../server/test/helpers.js';
async function python(settings){
  let child;
  try{return await new Promise((resolve,reject)=>{
    child=spawn('/usr/bin/python3',[fileURLToPath(new URL('./people-admin-browser.py',import.meta.url)),JSON.stringify(settings)],{detached:true});let stdout='',stderr='';
    const timer=setTimeout(()=>{try{process.kill(-child.pid,'SIGKILL');}catch{}reject(new Error('People browser exceeded 55 seconds'));},55000);
    child.stdout.on('data',value=>stdout+=value);child.stderr.on('data',value=>stderr+=value);
    child.on('error',error=>{clearTimeout(timer);reject(error);});child.on('close',code=>{clearTimeout(timer);resolve({code,stdout,stderr});});
  });}finally{if(child?.pid){try{process.kill(-child.pid,'SIGKILL');}catch{}}}
}
for(const mode of ['access','drafts','audit'])test('pinned browser people administration '+mode,{timeout:65000},async()=>{
  const server=await testServer();
  try{
    const api=server.agent(),auth=await api('POST','/auth/signup',{name:'Browser owner',email:'people-browser@admin.test',password:'correct-horse-battery'});
    const guest=server.agent(),guestAuth=await guest('POST','/auth/signup',{name:'Browser guest',email:'people-guest@admin.test',password:'correct-horse-battery'});
    const org=(await api('POST','/orgs',{name:'Browser administration'})).data.organization;
    const other=(await api('POST','/orgs',{name:'Other browser organization'})).data.organization;
    await api('POST','/orgs/'+org.id+'/members',{userId:guestAuth.data.user.id,role:'guest'});
    const project=(await api('POST','/orgs/'+org.id+'/projects',{key:'BROWSE',name:'Original project'})).data.project;
    const insert=server.ctx.db.prepare('INSERT INTO projects (id,org_id,key,name,description,archived,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)');
    for(let n=0;n<220;n++)insert.run('browser-project-'+n,org.id,'PAGE'+String(n).padStart(3,'0'),'Browser project '+n,'',n===219?1:0,server.ctx.now(),server.ctx.now());
    const team=(await api('POST','/orgs/'+org.id+'/teams',{name:'Browser team',description:'Before description'})).data.team;
    const result=await python({mode,url:server.url,cookie:auth.cookie,orgId:org.id,otherOrgId:other.id,userId:guestAuth.data.user.id,teamId:team.id,projectId:project.id});
    assert.equal(result.code,0,result.stderr+'\n'+result.stdout);assert.equal(JSON.parse(result.stdout.trim()).ok,true);
    if(mode==='access'){assert.equal((await api('GET','/orgs/'+org.id+'/members/'+guestAuth.data.user.id+'/access')).data.membership.role,'guest');assert.equal((await guest('GET','/projects/'+project.id)).status,403);}
    if(mode==='drafts'){const saved=(await guest('GET','/teams/'+team.id)).data.team;assert.equal(saved.name,'My chosen team');assert.equal(saved.description,'Peer description');}
  }finally{await server.close();}
});
test('pinned browser people action duplicate opaque-resource unmount and first-render paging custody',{timeout:65000},async()=>{
  const bundle=await build({entryPoints:[fileURLToPath(new URL('./people-harness.jsx',import.meta.url))],bundle:true,write:false,format:'iife',jsx:'automatic',jsxImportSource:'preact'});
  const server=createServer((req,res)=>{res.setHeader('content-type',req.url==='/bundle.js'?'text/javascript':'text/html');res.end(req.url==='/bundle.js'?bundle.outputFiles[0].text:'<div id="app"></div><script src="/bundle.js"></script>');});server.listen(0,'127.0.0.1');await once(server,'listening');
  try{const result=await python({mode:'lifetime',url:'http://127.0.0.1:'+server.address().port});assert.equal(result.code,0,result.stderr+'\n'+result.stdout);assert.equal(JSON.parse(result.stdout.trim()).ok,true);}
  finally{server.closeAllConnections();await new Promise(resolve=>server.close(resolve));}
});
